<?php
function product_card(array $p):void { ?>
<div class="col-6 col-md-4 col-xl-3"><div class="product-item"><div class="product-img"><?php if($p['sale_price']!==null&&$p['price']<$p['regular_price']): ?><span class="type discount">Sale</span><?php endif; ?><a href="<?= url('shop-single.php?slug='.rawurlencode($p['slug'])) ?>"><img loading="lazy" src="<?= h(url($p['image']?:'assets/img/logo/favicon.png')) ?>" alt="<?= h($p['name']) ?>"></a></div><div class="product-content"><h3 class="product-title"><a href="<?= url('shop-single.php?slug='.rawurlencode($p['slug'])) ?>"><?= h($p['name']) ?></a></h3><div class="product-price"><?php if($p['regular_price']>$p['price']): ?><del><?= h(money($p['regular_price'])) ?></del><?php endif; ?><span><?= h(money($p['price'])) ?></span></div><div class="product-card-actions"><?php if(!available($p,1)): ?><span>Out of stock</span><?php elseif($p['type']==='variable'): ?><a class="theme-btn" href="<?= url('shop-single.php?slug='.rawurlencode($p['slug'])) ?>">Choose options</a><?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="cart_add"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button class="theme-btn" aria-label="Add <?= h($p['name']) ?> to cart"><i class="far fa-shopping-bag"></i> Add</button></form><?php endif; ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button class="btn" aria-label="Save <?= h($p['name']) ?> to wishlist"><i class="far fa-heart"></i></button></form></div></div></div></div>
<?php }
function pagination(int $total,int $size,int $page):void{if($total<=$size)return;echo '<nav aria-label="Pagination"><ul class="pagination">';for($i=max(1,$page-3);$i<=min((int)ceil($total/$size),$page+3);$i++){echo '<li class="page-item '.($i===$page?'active':'').'"><a class="page-link" href="?'.h(http_build_query(array_merge($_GET,['page'=>$i]))).'">'.$i.'</a></li>';}echo '</ul></nav>';}
function product_grid(array $products):void{echo '<div class="row store-grid">';foreach($products as $product)product_card($product);if(!$products)echo '<p>No products match your selection.</p>';echo '</div>';}
?>
<?php if($view==='home'): $banners=rows('SELECT * FROM banners WHERE active=1 ORDER BY sort_order,id LIMIT 8');if(!$banners)$banners=[null];$heroProduct=row('SELECT * FROM products WHERE status="publish" AND image IS NOT NULL ORDER BY featured DESC,id DESC LIMIT 1'); ?>
<div class="hero-section hs-1"><div class="<?= count($banners)>1?'hero-slider owl-carousel owl-theme':'' ?>"><?php foreach($banners as $banner): ?><div class="hero-single" style="background-image:url(<?= url('assets/img/hero/bg.png') ?>)"><div class="container position-relative"><div class="row align-items-center"><div class="col-lg-6"><div class="hero-content"><h6 class="hero-sub-title"><?= h(setting('site_name')) ?></h6><h1 class="hero-title"><?= h($banner['title']??setting('tagline')) ?></h1><?php if(!empty($banner['description'])): ?><p><?= h($banner['description']) ?></p><?php endif; ?><div class="hero-btn"><a href="<?= h($banner?safe_link($banner['link']):url('shop-grid.php')) ?>" class="theme-btn"><?= h($banner['button_text']??'Shop now') ?><i class="fas fa-arrow-right"></i></a><a href="<?= url('about.php') ?>" class="theme-btn theme-btn2">About us<i class="fas fa-arrow-right"></i></a></div></div></div><div class="col-lg-6"><div class="hero-right"><div class="hero-img"><img src="<?= h(url($banner['image']??$heroProduct['image']??'assets/img/hero/hero-1.png')) ?>" alt="<?= h($banner['title']??$heroProduct['name']??setting('site_name')) ?>"></div></div></div></div></div></div><?php endforeach; ?></div></div>
<div class="category-area pt-60"><div class="container"><div class="site-heading-inline"><h2 class="site-title">Shop by category</h2><a href="<?= url('category.php') ?>">View all <i class="far fa-arrow-right"></i></a></div><div class="row"><?php foreach(rows('SELECT c.*,COALESCE(c.image,(SELECT p.image FROM products p JOIN product_categories pc ON pc.product_id=p.id WHERE pc.category_id=c.id AND p.status="publish" AND p.image IS NOT NULL LIMIT 1)) cover FROM categories c WHERE active=1 AND parent_id IS NULL ORDER BY sort_order,name LIMIT 8') as $c): ?><div class="col-6 col-md-3 col-lg-2 mb-4"><a class="category-item" href="<?= url('shop-grid.php?category='.rawurlencode($c['slug'])) ?>"><?php if($c['cover']): ?><img loading="lazy" src="<?= h(url($c['cover'])) ?>" alt=""><?php endif; ?><h6><?= h($c['name']) ?></h6></a></div><?php endforeach; ?></div></div></div>
<?php foreach(explode(',',setting('home_sections','featured,new,sale,blog')) as $section): $section=trim($section);if($section==='blog')continue;$defs=['featured'=>['Featured products','featured=1'],'new'=>['New arrivals','1=1'],'sale'=>['Special offers','sale_price IS NOT NULL AND price<regular_price'],'bestsellers'=>['Best sellers','id IN (SELECT product_id FROM order_items WHERE product_id IS NOT NULL)']];if(!isset($defs[$section]))continue;$list=rows('SELECT * FROM products WHERE status="publish" AND '.$defs[$section][1].' ORDER BY '.($section==='bestsellers'?'(SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.product_id=products.id AND o.status NOT IN ("cancelled","refunded")) DESC':'created_at DESC').' LIMIT 8');if(!$list)continue; ?><section class="product-area pt-60"><div class="container"><div class="site-heading-inline"><h2 class="site-title"><?= $defs[$section][0] ?></h2><a href="<?= url('shop-grid.php') ?>">View all <i class="far fa-arrow-right"></i></a></div><?php product_grid($list); ?></div></section><?php endforeach; ?>
<?php if(in_array('blog',explode(',',setting('home_sections')))): ?><section class="blog-area py-60"><div class="container"><div class="site-heading-inline"><h2 class="site-title">Latest articles</h2><a href="<?= url('blog.php') ?>">View all</a></div><div class="row"><?php foreach(rows('SELECT * FROM content WHERE type="post" AND status="publish" ORDER BY published_at DESC LIMIT 3') as $b): ?><div class="col-md-4"><div class="blog-item"><?php if($b['image']): ?><div class="blog-item-img"><img loading="lazy" src="<?= h(url($b['image'])) ?>" alt="<?= h($b['title']) ?>"></div><?php endif; ?><div class="blog-item-info"><h3 class="blog-title"><a href="<?= url('blog-single.php?slug='.rawurlencode($b['slug'])) ?>"><?= h($b['title']) ?></a></h3><a class="theme-btn" href="<?= url('blog-single.php?slug='.rawurlencode($b['slug'])) ?>">Read more</a></div></div></div><?php endforeach; ?></div></div></section><?php endif; ?>
<?php elseif($view==='shop'): $where=['p.status="publish"'];$params=[];$q=trim($_GET['q']??'');$category=trim($_GET['category']??'');if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR p.short_description LIKE ?)';$params=array_merge($params,array_fill(0,3,'%'.$q.'%'));track('search',null,$q);}if($category!==''){$selected=row('SELECT * FROM categories WHERE slug=? AND active=1',[$category]);if($selected){$ids=[(int)$selected['id']];$all=rows('SELECT id,parent_id FROM categories WHERE active=1');do{$old=count($ids);foreach($all as $c)if(in_array((int)$c['parent_id'],$ids)&&!in_array((int)$c['id'],$ids))$ids[]=(int)$c['id'];}while(count($ids)>$old);$where[]='EXISTS(SELECT 1 FROM product_categories pc WHERE pc.product_id=p.id AND pc.category_id IN ('.implode(',',$ids).'))';track('category_view',(int)$selected['id']);}else $where[]='1=0';}foreach(['min'=>'>=','max'=>'<='] as $k=>$op)if(isset($_GET[$k])&&$_GET[$k]!==''&&is_numeric($_GET[$k])){$where[]="p.price $op ?";$params[]=max(0,(float)$_GET[$k]);}$sort=['new'=>'p.created_at DESC','price_asc'=>'p.price ASC','price_desc'=>'p.price DESC','name'=>'p.name ASC'][$_GET['sort']??'new']??'p.created_at DESC';$page=max(1,(int)($_GET['page']??1));$total=(int)scalar('SELECT COUNT(*) FROM products p WHERE '.implode(' AND ',$where),$params);$list=rows('SELECT p.* FROM products p WHERE '.implode(' AND ',$where).' ORDER BY '.$sort.' LIMIT 12 OFFSET '.(($page-1)*12),$params); ?>
<div class="shop-area py-90"><div class="container"><div class="row"><aside class="col-lg-3"><div class="shop-sidebar"><div class="shop-widget"><h4 class="shop-widget-title">Filter products</h4><form class="store-form"><label for="q">Search</label><input id="q" name="q" value="<?= h($q) ?>"><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach(rows('SELECT * FROM categories WHERE active=1 ORDER BY name') as $c): ?><option value="<?= h($c['slug']) ?>" <?= $category===$c['slug']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select><label for="min">Minimum price</label><input id="min" type="number" min="0" step="0.01" name="min" value="<?= h($_GET['min']??'') ?>"><label for="max">Maximum price</label><input id="max" type="number" min="0" step="0.01" name="max" value="<?= h($_GET['max']??'') ?>"><label for="sort">Sort</label><select id="sort" name="sort"><?php foreach(['new'=>'Newest','price_asc'=>'Price: low to high','price_desc'=>'Price: high to low','name'=>'Name'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($_GET['sort']??'new')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select><button class="theme-btn">Apply filters</button></form></div></div></aside><div class="col-lg-9"><div class="shop-sort mb-4"><h5><?= $total ?> products<?= isset($selected['name'])?' in '.h($selected['name']):'' ?></h5></div><?php product_grid($list);pagination($total,12,$page); ?></div></div></div></div>
<?php elseif($view==='categories'): ?><div class="category-area py-90"><div class="container"><div class="row"><?php foreach(rows('SELECT c.*,COUNT(pc.product_id) product_count FROM categories c LEFT JOIN product_categories pc ON pc.category_id=c.id WHERE c.active=1 GROUP BY c.id ORDER BY c.sort_order,c.name') as $c): ?><div class="col-6 col-md-4 col-lg-3 mb-4"><a class="category-item" href="<?= url('shop-grid.php?category='.rawurlencode($c['slug'])) ?>"><?php if($c['image']): ?><img loading="lazy" src="<?= h(url($c['image'])) ?>" alt=""><?php endif; ?><h5><?= h($c['name']) ?></h5><span><?= $c['product_count'] ?> products</span></a></div><?php endforeach; ?></div></div></div>
<?php elseif($view==='product'): $gallery=rows('SELECT * FROM product_images WHERE product_id=? ORDER BY sort_order',[$p['id']]);$categories=rows('SELECT c.* FROM categories c JOIN product_categories pc ON pc.category_id=c.id WHERE pc.product_id=?',[$p['id']]);$variants=rows('SELECT * FROM product_variants WHERE product_id=? AND active=1',[$p['id']]); ?>
<div class="shop-single py-90"><div class="container"><div class="row"><div class="col-lg-6"><div class="shop-single-gallery store-gallery"><a class="popup-gallery" href="<?= h(url($p['image']?:'assets/img/logo/favicon.png')) ?>"><img src="<?= h(url($p['image']?:'assets/img/logo/favicon.png')) ?>" alt="<?= h($p['name']) ?>"></a><div class="store-gallery-thumbs"><?php foreach($gallery as $g): ?><a href="<?= h(url($g['path'])) ?>"><img loading="lazy" src="<?= h(url($g['path'])) ?>" alt="<?= h($p['name']) ?>"></a><?php endforeach; ?></div></div></div><div class="col-lg-6"><div class="shop-single-info"><h2 class="shop-single-title"><?= h($p['name']) ?></h2><div class="shop-single-price"><?php if($p['regular_price']>$p['price']): ?><del><?= h(money($p['regular_price'])) ?></del><?php endif; ?><span class="amount"><?= h(money($p['price'])) ?></span></div><div class="store-content mb-3"><?= $p['short_description'] ?></div><p class="mb-3"><?= available($p,1)?'In stock':'Out of stock' ?><?= $p['manage_stock']?' — '.h((float)$p['stock']).' available':'' ?></p><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="cart_add"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><?php if($p['type']==='variable'): ?><label for="variant">Choose an option</label><select name="variant_id" id="variant" required><option value="">Select variant</option><?php foreach($variants as $v): ?><option value="<?= $v['id'] ?>"><?= h(implode(' / ',array_map(fn($x)=>is_scalar($x)?$x:json_encode($x),json_decode($v['attributes'],true)?:[])).' — '.money($v['price'])) ?></option><?php endforeach; ?></select><?php endif; ?><label for="quantity">Quantity</label><input id="quantity" type="number" min="1" max="99" name="quantity" value="1" style="max-width:110px"><button class="theme-btn" <?= !available($p,1)?'disabled':'' ?>><i class="far fa-shopping-bag"></i> Add to cart</button></form><form method="post" class="mt-3"><?= csrf_field() ?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button class="btn"><i class="far fa-heart"></i> Add to wishlist</button></form><div class="shop-single-sortinfo mt-4"><p>SKU: <?= h($p['sku']?:'Not specified') ?></p><p>Categories: <?php foreach($categories as $c): ?><a href="<?= url('shop-grid.php?category='.rawurlencode($c['slug'])) ?>"><?= h($c['name']) ?></a> <?php endforeach; ?></p><?php if($p['tags']): ?><p>Tags: <?= h($p['tags']) ?></p><?php endif; ?></div></div></div></div><div class="shop-single-details pt-60"><h3 class="mb-4">Product description</h3><div class="store-content"><?= $p['description'] ?></div><?php if($p['attributes']&&$p['attributes']!=='[]'): ?><h4>Attributes</h4><dl><?php foreach(json_decode($p['attributes'],true)?:[] as $k=>$a): ?><dt><?= h($a['name']??$k) ?></dt><dd><?= h(implode(', ',$a['values']??[])?:($a['value']??'')) ?></dd><?php endforeach; ?></dl><?php endif; ?><?php if($p['weight']): ?><p>Weight: <?= h($p['weight']) ?></p><?php endif; ?></div><section class="pt-60"><h3 class="mb-4">Related products</h3><?php product_grid(rows('SELECT DISTINCT p.* FROM products p JOIN product_categories pc ON pc.product_id=p.id WHERE p.status="publish" AND p.id<>? AND pc.category_id IN(SELECT category_id FROM product_categories WHERE product_id=?) LIMIT 4',[$p['id'],$p['id']])); ?></section></div></div>
